            std::array<long double,3> target{};Json origin;
            const auto& proof=e.at("proof");auto part=[&](const std::string& id)->const TriangleMesh&{auto it=std::find_if(out.parts.begin(),out.parts.end(),[&](const auto& p){return p.id==id;});need(it!=out.parts.end(),"mesh part missing");return it->mesh;};
            if(cross&&qi==0){auto id=proof.at("edge_part").get<std::string>(),fid=proof.at("face_part").get<std::string>();const auto& mesh=part(id);const auto& fm=part(fid);const auto& u=mesh.points.at(proof.at("edge_vertex_indices")[0].get<std::size_t>());const auto& v=mesh.points.at(proof.at("edge_vertex_indices")[1].get<std::size_t>());auto t=fm.triangles.at(proof.at("target_triangle_id").get<std::size_t>());auto a=fm.points[t[0]],b=fm.points[t[1]],c=fm.points[t[2]];std::array<long double,3> ab{},ac{},n{};for(int k=0;k<3;++k){ab[k]=(long double)b[k]-a[k];ac[k]=(long double)c[k]-a[k];}for(int k=0;k<3;++k)n[k]=ab[(k+1)%3]*ac[(k+2)%3]-ab[(k+2)%3]*ac[(k+1)%3];long double du=0,dv=0;for(int k=0;k<3;++k){du+=n[k]*((long double)u[k]-a[k]);dv+=n[k]*((long double)v[k]-a[k]);}need(du*dv<0,"non-strict edge query");auto alpha=du/(du-dv);for(int k=0;k<3;++k)target[k]=(long double)u[k]+alpha*((long double)v[k]-u[k]);int side=e.at("part_ids")[0]==id?0:1;origin={{"part_id",id},{"triangle_id",proof.at("triangle_ids")[side]}};
            }else if(cross&&qi<3){auto id=proof.at("edge_part").get<std::string>();auto vi=proof.at("edge_vertex_indices")[qi-1].get<std::size_t>();auto p=part(id).points.at(vi);for(int k=0;k<3;++k)target[k]=p[k];origin={{"part_id",id},{"vertex_index",vi}};
            }else if(common&&qi==0){for(int k=0;k<3;++k)target[k]=proof.at("point_mm")[k].get<double>();origin={{"kind","existing_mesh_common_interior"}};
            }else{std::size_t side=qi-(cross?3:common?1:0);auto id=e.at("part_ids")[side].get<std::string>();auto ti=(proof.contains("triangle_ids")?proof.at("triangle_ids"):out.report.at("relations").at("pairs")[expected].at("triangle_ids"))[side].get<std::size_t>();const auto& mesh=part(id);for(int k=0;k<3;++k){for(auto vi:mesh.triangles.at(ti))target[k]+=(long double)mesh.points[vi][k];target[k]/=3;}origin={{"part_id",id},{"triangle_id",ti}};}
            need(q.at("origin")==origin,"query origin mismatch");for(int k=0;k<3;++k)need(std::abs((long double)q.at("point_mm")[k].get<double>()-target[k])<=64*std::numeric_limits<double>::epsilon()*scale,"query coordinate mismatch");
            need(q.at("measurements").is_array()&&q.at("measurements").size()==2,"measurement count");for(int i=0;i<2;++i){const auto& m=q.at("measurements")[i];const auto& b=row.at("bindings")[i];fields(m,{"part_id","boundary_distance_mm","point_states","nearest_face_candidates","nearest_ambiguous"});need(m.at("part_id")==e.at("part_ids")[i],"measurement part mismatch");double distance=number(m.at("boundary_distance_mm"));++distances;need(m.at("point_states").is_array()&&m.at("point_states").size()==3,"classification sequence");std::set<std::string> states;for(int j=0;j<3;++j){const auto& s=m.at("point_states")[j];fields(s,{"tolerance_mm","state"});need(s.at("tolerance_mm")==a.at("classification_tolerances_mm")[j]&&s.at("state").is_string(),"classification tolerance");auto state=s.at("state").get<std::string>();need(state=="IN"||state=="OUT"||state=="ON"||state=="UNKNOWN","classification state");states.insert(state);++classifications;}auto faceCount=b.at("face_count").get<std::size_t>();faceTests+=faceCount;const auto& candidates=m.at("nearest_face_candidates");need(candidates.is_array()&&!candidates.empty()&&candidates.size()<=faceCount&&m.at("nearest_ambiguous")==bool(candidates.size()!=1),"nearest face profile");std::set<std::size_t> seen;double nearest=1e100;for(const auto& f:candidates){fields(f,{"face_index","surface_type","distance_mm"});need(seen.insert(index(f.at("face_index"),faceCount-1)).second,"duplicate nearest face");need(f.at("surface_type").is_string()&&QRegularExpression("^GeomAbs_[A-Za-z]+$").match(QString::fromStdString(f.at("surface_type"))).hasMatch(),"surface type");double d=number(f.at("distance_mm"));need(std::abs(d-distance)<=1e-7,"nearest distance discrepancy");nearest=std::min(nearest,d);}need(std::abs(nearest-distance)<=1e-7,"boundary distance discrepancy");if(qi==0&&(cross||common)){double margin=10*std::max(1e-5,b.at("max_entity_tolerance_mm").get<double>());stable.push_back(states.size()==1&&distance>margin+rounding?*states.begin():"TOLERANCE");}}
